/*
 * A217522  Squarefree ternary sequence derived from bi-infinite squarefree
 *          ternary sequence of Kurosaki.
 * https://oeis.org/A217522
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   generated by iterating the morphism 0->012, 1->103, 2->430,
 *            3->521, 4->254, 5->345 starting from 0 and then mapping 3,4,5 to
 *            2,1,0
 * Range:     u8 n <= 62, u16 n <= 62, u32 n <= 62, u64 n <= 62, u128 n <= 62,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>

/* mapping from digits 0..5 to final 0..2 */
static const seq_t map5to3[6] = { (seq_t)0, 1, 2, 2, 1, 0 };

/* cache of digits after each expansion; still 0..5 */
static uint8_t *digits = NULL;
static size_t digit_len = 0;
static size_t digit_cap = 0;

/* Ensure digits[] contains at least n entries (n >= 1). */
static void ensure_upto(idx_t n)
{
    if (digits == NULL)
    {
        /* starting sequence: single 0 */
        digit_cap = 1;
        digits = (uint8_t *)malloc(digit_cap);
        if (digits == NULL) exit(EXIT_FAILURE);
        digits[0] = 0;
        digit_len = 1;
    }

    size_t need = (size_t)n;
    while (digit_len < need)
    {
        size_t new_len = digit_len * 3;
        uint8_t *next = (uint8_t *)malloc(new_len);
        if (next == NULL) exit(EXIT_FAILURE);

        size_t pos = 0;
        for (size_t i = 0; i < digit_len; ++i)
        {
            uint8_t x = digits[i];
            switch (x)
            {
                case 0: next[pos++] = 0; next[pos++] = 1; next[pos++] = 2; break;
                case 1: next[pos++] = 1; next[pos++] = 0; next[pos++] = 3; break;
                case 2: next[pos++] = 4; next[pos++] = 3; next[pos++] = 0; break;
                case 3: next[pos++] = 5; next[pos++] = 2; next[pos++] = 1; break;
                case 4: next[pos++] = 2; next[pos++] = 5; next[pos++] = 4; break;
                case 5: next[pos++] = 3; next[pos++] = 4; next[pos++] = 5; break;
            }
        }

        free(digits);
        digits = next;
        digit_len = new_len;
        digit_cap = new_len;
    }
}

/* Main function required by the build. */
seq_t a(idx_t n)
{
    if (n == 0)
        return 0; /* a(0) is undefined, return 0 for safety */

    ensure_upto(n);
    uint8_t d = digits[(size_t)(n - 1)];   /* 0..5 */
    return map5to3[(size_t)d];             /* 0..2 */
}
